import socket, time

def probe(port, attempts=4, timeout=20):
    results = []
    for i in range(attempts):
        t0 = time.time()
        s = socket.socket()
        s.settimeout(timeout)
        try:
            s.connect(("192.168.1.100", port))
            results.append(("OPEN", round(time.time()-t0, 2)))
            try:
                s.settimeout(6)
                banner = s.recv(512)
                results.append(("banner", banner[:120]))
            except Exception as e:
                results.append(("banner_err", type(e).__name__))
            s.close()
        except socket.timeout:
            results.append(("TIMEOUT", round(time.time()-t0, 2)))
        except ConnectionRefusedError:
            results.append(("REFUSED", round(time.time()-t0, 2)))
        except OSError as e:
            results.append((f"OSERR:{e.errno}:{e.strerror}", round(time.time()-t0, 2)))
        finally:
            s.close()
    return results

for p in (80, 3306):
    print(f"--- port {p} ---")
    for r in probe(p):
        print("  ", r)
EOF
